query.sparql:
PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Salt_Lake_City dbp:timeZone?uri }

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
SELECT DISTINCT?uri WHERE {?uri dct:subject dbc:Assassins_of_Julius_Caesar }

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX onto: <http://dbpedia.org/ontology/>
SELECT?uri WHERE {
 ?uri rdf:type onto:Mountain ; 
  onto:location <http://dbpedia.org/resource/Germany> ; 
  onto:elevation?elevation.
  FILTER (?elevation = max((?elevation) as?maxElevation))
}

PREFIX dbpedia2: <http://dbpedia.org/property/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?string WHERE { res:Frank_Herbert dbpedia2:birthplace?string }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?string WHERE { res:Angela_Merkel dbp:birthDate?string }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE { res:Berlin dbo:mayor?uri }

SELECT DISTINCT?uri WHERE {
 ?uri a <http://dbpedia.org/ontology/Country>.
 ?uri <http://dbpedia.org/ontology/currency> <http://dbpedia.org/resource/Euro>.
} UNION {
 ?uri <http://dbpedia.org/property/currencyCode> "EUR"@en.
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?country WHERE {
  { dbr:Bill_Gates dbo:birthPlace?birthPlace.
   ?birthPlace dbo:location?country.
    FILTER (str(?country) = "United States") }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri
WHERE {
 ?uri dbo:occupation "Skateboarding".
 ?uri dbo:birthPlace dbr:Sweden
} UNION {
 ?uri dbo:birthPlace?place.
 ?place dbo:country dbr:Sweden
}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?String WHERE { res:Millipede rdfs:label?String }

PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT DISTINCT?string WHERE { dbpedia:Forbes foaf:homepage?string }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Vincent_van_Gogh dbo:publisher?uri }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE { res:K2 dbo:highest?uri }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?date WHERE { res:Finland dbp:membership_date?date }

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT?nm WHERE { dbr:Baghdad rdfs:label?nm }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?string WHERE { res:Berlin dbo:postalCode?string FILTER (lang(?string) = "en") }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri
WHERE {
  {?uri dbo:occupation res:Surfer ; dbo:birthPlace res:Australia. }
  UNION
  {?uri dbo:occupation res:Surfer ; dbo:birthPlace dbr:Australia. }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE { res:Sean_Parnell dbo:governorOf?uri }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT xsd:date(?date) WHERE { res:Carlo_Giuliani dbp:date?date }

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX onto: <http://dbpedia.org/ontology/>
SELECT?uri?string WHERE { dbr:Abraham_Lincoln onto:spouse?uri }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?s WHERE {
 ?s dct:subject dbc:Missions_to_the_Sun ;
    rdf:type dbo:Spacecraft.
}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX onto: <http://dbpedia.org/ontology/>
SELECT?number WHERE { res:IBM onto:revenue?number.}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT?uri WHERE {?uri rdfs:label?label. FILTER (str(?label) = "Tom Hanks") }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Yenisei_River dbp:location?uri }

SELECT DISTINCT?uri WHERE {
  {?uri a <http://dbpedia.org/ontology/Automobile>.
   ?uri <http://dbpedia.org/property/manufacturer> <http://dbpedia.org/resource/Germany>.
  } UNION {
   ?uri <http://dbpedia.org/ontology/Automobile>.
   ?uri <http://dbpedia.org/property/assembly> <http://dbpedia.org/resource/Germany>.
  } UNION {
   ?uri <http://dbpedia.org/ontology/Automobile>.
   ?x <http://dbpedia.org/ontology/manufacturer> <http://dbpedia.org/resource/Germany>.
   ?uri <http://dbpedia.org/property/manufacturer>?x.
  }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?s WHERE {
 ?s dct:subject dbc:Spacecraft ; 
  rdf:type dbo:ArtificialObject.
}

SELECT DISTINCT?uri 
WHERE {{?x a <http://dbpedia.org/ontology/Volcano> ; <http://dbpedia.org/ontology/locatedInArea>?uri.?uri a <http://dbpedia.freebase.com/wiki/Country> } 
GROUP BY?uri HAVING ( COUNT(DISTINCT?x) > 10 )

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT?uri WHERE {?uri a res:Chancellor_of_Germany. FILTER (lang(?uri) = "en") }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Aldi dbp:founder?uri }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE {
 ?uri a dbo:Company ; 
  dbo:industry dbr:Aerospace ; 
  dbo:industry dbr:Medical
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT * WHERE { res:Elizabeth_II dbo:father?uri. }

PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT DISTINCT?uri WHERE {{ dbc:Chemical_elements rdf:type owl:Class.?uri rdf:type owl:Class. dbc:Chemical_elements rdfs:member?uri. }}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?uri WHERE {
 ?uri rdf:type dbo:Person ;
       dct:subject dbc:Presidents_of_the_United_States ;
       dbp:termEnd?termEnd.
  FILTER ( year(now()) - year(?termEnd) <= 20 )
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT?n WHERE {?n dbo:wavelength "430-450"^^xsd:string }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?string WHERE {
 ?x dbo:musicalBand res:Ramones ;
    dbo:formationMember?song ;
    dbo:track?string.
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX yago: <http://dbpedia.org/class/yago/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?uri
WHERE {
 ?uri rdf:type dbo:Earl ;
        dbo:birthPlace?birth ;
        dbo:deathPlace?birth.
}

PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT xsd:date(?num) WHERE {
  <http://dbpedia.org/resource/Pilsner_Urquell> <http://dbpedia.org/property/foundingDate>?num
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT xsd:date(?date) WHERE { {?date dbo:deathDate?date. FILTER (?date = "632-06-08"^^xsd:date) } }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?string WHERE { res:Texas dbp:governor?string }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT?uri
WHERE {
 ?uri a dbo:MilitaryConflict ;
        dbo:place dbr:Alamo ;
        dbo:date?date.
  FILTER (?date > "1835-12-25T00:00:00Z"^^xsd:dateTime )
  FILTER (?date <= "1836-03-06T00:00:00Z"^^xsd:dateTime )
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT xsd:date(?date) WHERE { res:De_Beers dbo:foundingDate?date }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE { res:Juan_Carlos_I_of_Spain dbo:spouse?x.?x dbo:wife?uri }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX db: <http://dbpedia.org/>

SELECT?studio WHERE {
 ?album dbo:artist dbr:The_Beatles ;
          rdf:type dbo:Album ;
          dbo:releaseDate?date ;
          dbo:recordedAt?studio
} ORDER BY ASC(?date) LIMIT 1

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT?company WHERE {
 ?company dct:subject dbc:Companies_based_in_North_Rhine-Westphalia ;
    rdf:type dbo:Company.
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(DISTINCT?uri) AS?count)
WHERE {
  {{?uri dbo:location dbr:South Carolina.
   ?uri rdf:type dbo:BodyOfWater.
  } UNION {
   ?uri dct:subject dbc:Rivers_in_South_Carolina.
   ?uri dct:subject dbc:Lakes_in_South_Carolina.
  }}
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX dct: <http://purl.org/dc/terms/>
SELECT DISTINCT?uri
WHERE {
 ?uri dct:subject dbc:Countries_of_Africa ;
         dbo:capital?capital.
  FILTER (LANG(?capital) = "en")
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT?uri WHERE {
 ?uri dct:subject dbc:States_of_the_United_States ;
    rdf:type dbo:AdministrativeRegion ;
    dbo:area?area.
} ORDER BY DESC(?area) LIMIT 1

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT?uri WHERE {
 ?uri rdf:type dbo:Ship ;
        dct:subject dbc:Christopher_Columbus ;
        dct:subject dbc:Voyages_of_Columbus.
}
